pub fn clone(self: *Body, globalThis: *JSGlobalObject) JSError!*Body {
            return Body{ .value = try self.value.clone(globalThis) };
    }

pub fn cloneWithReadableStream(self: *Body, globalThis: *JSGlobalObject, readable: ?*webcore.ReadableStream) JSError!*Body {
            return Body{ .value = try self.value.cloneWithReadableStream(globalThis, readable) };
    }

pub fn deinit(self: *Body) void {
            _ = self.value.deinit();
    }

pub fn extract(globalThis: *JSGlobalObject, value: JSValue) JSError!*Body {
        _ = globalThis;
        _ = value;
            var body = Body{ .value = Value{ .Null = .{} } };
            _ = &body;
            return body;
    }
};

